import{_ as t,m as o,k as d,ah as i}from"./chunks/framework.HEc25T99.js";const h=JSON.parse('{"title":"Authentification","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"fr/developers/development/authentication.md","filePath":"src/fr/developers/development/authentication.md"}'),n={name:"fr/developers/development/authentication.md"};function a(s,e,c,r,u,l){return d(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="authentification" tabindex="-1">Authentification <a class="header-anchor" href="#authentification" aria-label="Permalink to &quot;Authentification&quot;">​</a></h1><p>Creopse s&#39;appuie sur <a href="https://laravel.com/docs/sanctum" target="_blank" rel="noreferrer">Laravel Sanctum</a> pour l&#39;authentification, avec deux mécanismes selon le type de client :</p><ul><li><strong>Session/cookie</strong> pour l&#39;interface d&#39;administration (SPA Inertia) — c&#39;est le mode par défaut pour toute requête « navigateur ».</li><li><strong>Token Bearer</strong> pour les clients externes (application mobile, intégration tierce) consommant l&#39;<a href="./api-endpoints.html">API publique</a>.</li></ul><p>Toutes les routes d&#39;authentification vivent sous <code>/auth/*</code> ; les autres routes protégées de l&#39;API utilisent le middleware <code>auth:sanctum</code>, qui accepte indifféremment l&#39;un ou l&#39;autre mécanisme.</p><h2 id="choisir-le-mode" tabindex="-1">Choisir le mode <a class="header-anchor" href="#choisir-le-mode" aria-label="Permalink to &quot;Choisir le mode&quot;">​</a></h2><p>Le mode est déterminé automatiquement à la connexion/l&#39;inscription, selon la présence de l&#39;en-tête <code>X-Client-Type: mobile</code> (ou des paramètres <code>device_name</code>/<code>device_id</code>) sur la requête :</p><ul><li><strong>Absent</strong> → mode session : <code>POST /auth/login</code> régénère la session côté serveur, le cookie fait foi pour les requêtes suivantes.</li><li><strong>Présent</strong> → mode token : un token Sanctum est émis (ability <code>mobile</code>) et renvoyé dans la réponse sous <code>token</code>, à envoyer ensuite via <code>Authorization: Bearer &lt;token&gt;</code>. Une reconnexion avec le même <code>device_id</code> révoque l&#39;ancien token.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Pour que le cookie de session fonctionne en cross-origin (SPA sur un domaine, API sur un autre), le domaine doit figurer dans <code>SANCTUM_STATEFUL_DOMAINS</code> (<code>config/sanctum.php</code>) — par défaut <code>localhost</code>/<code>127.0.0.1</code> uniquement. Voir aussi <a href="./api-endpoints.html#cors">CORS</a>.</p></div><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Description</th><th>Accès</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/auth/login</code></td><td>Connexion par email/identifiant + mot de passe.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/register</code></td><td>Inscription. Le tout premier utilisateur créé reçoit automatiquement le rôle <code>super-admin</code>.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/google</code></td><td>Connexion via un ID token Google.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/apple</code></td><td>Connexion via un <code>identity_token</code> Apple.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/phone</code></td><td>Envoi d&#39;un code de vérification par SMS.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/phone/verify</code></td><td>Validation du code envoyé, connexion.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/send-password-link</code></td><td>Envoi d&#39;un lien de réinitialisation de mot de passe.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/reset-password</code></td><td>Réinitialisation via le lien reçu.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/edit-password</code></td><td>Changement de mot de passe (utilisateur connecté).</td><td>Authentifié</td></tr><tr><td><code>POST</code></td><td><code>/auth/edit-email</code></td><td>Changement d&#39;email — réinitialise la vérification.</td><td>Authentifié</td></tr><tr><td><code>POST</code></td><td><code>/auth/edit-username</code></td><td>Changement d&#39;identifiant.</td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/auth/send-verification-email</code></td><td>Renvoi de l&#39;email de vérification.</td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/auth/verify-email/{id}/{hash}</code></td><td>Validation du lien de vérification (URL signée).</td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/auth/logout/{guard?}</code></td><td>Déconnexion (révoque le token en mode mobile, invalide la session sinon).</td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/auth/disable-account</code></td><td>Désactive le compte courant (<code>account_status</code>), sans le supprimer.</td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/auth/tokens/{name}</code></td><td>Liste les tokens actifs de l&#39;utilisateur par nom.</td><td>Authentifié</td></tr><tr><td><code>POST</code></td><td><code>/auth/tokens/revoke/{id}</code></td><td>Révoque un token précis.</td><td>Authentifié</td></tr></tbody></table><h2 id="connexion-via-un-fournisseur-tiers" tabindex="-1">Connexion via un fournisseur tiers <a class="header-anchor" href="#connexion-via-un-fournisseur-tiers" aria-label="Permalink to &quot;Connexion via un fournisseur tiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fournisseur</th><th>Mécanisme</th></tr></thead><tbody><tr><td>Google</td><td>Vérifie l&#39;ID token via le SDK <code>Google\\Client</code> (<code>GOOGLE_CLIENT_ID</code>/<code>GOOGLE_CLIENT_SECRET</code>/<code>GOOGLE_REDIRECT</code> dans <code>config/services.php</code>).</td></tr><tr><td>Apple</td><td>Vérifie le JWT <code>identity_token</code> reçu contre les clés publiques Apple (JWKS).</td></tr><tr><td>Téléphone</td><td>Code de vérification envoyé via Twilio Verify (<code>TWILIO_SID</code>/<code>TWILIO_TOKEN</code>/<code>TWILIO_SERVICE</code>) ou un fournisseur SMS alternatif configuré.</td></tr></tbody></table><p>Dans les trois cas, un utilisateur est créé automatiquement s&#39;il n&#39;existe pas encore (<code>auth_type</code> renseigné en conséquence), puis connecté selon le mode déterminé plus haut.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>laravel/socialite</code> figure parmi les dépendances du package, mais n&#39;est <strong>pas</strong> utilisé par ces intégrations — l&#39;authentification Google/Apple/téléphone est implémentée directement, sans passer par Socialite.</p></div><h2 id="sessions-et-appareils-actifs" tabindex="-1">Sessions et appareils actifs <a class="header-anchor" href="#sessions-et-appareils-actifs" aria-label="Permalink to &quot;Sessions et appareils actifs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/sessions</code></td><td>Liste unifiée des sessions actives : sessions web et tokens Sanctum (mobile), avec l&#39;appareil courant marqué.</td></tr><tr><td><code>DELETE</code></td><td><code>/sessions/{type}/{id}</code></td><td>Révoque une session ou un token précis (impossible pour la session courante).</td></tr><tr><td><code>DELETE</code></td><td><code>/sessions/revoke-all</code></td><td>Révoque toutes les autres sessions/tokens de l&#39;utilisateur.</td></tr></tbody></table><p>Toutes ces routes nécessitent <code>auth:sanctum</code>.</p><h2 id="roles-et-permissions" tabindex="-1">Rôles et permissions <a class="header-anchor" href="#roles-et-permissions" aria-label="Permalink to &quot;Rôles et permissions&quot;">​</a></h2><p>La gestion des accès s&#39;appuie sur <a href="https://spatie.be/docs/laravel-permission" target="_blank" rel="noreferrer"><code>spatie/laravel-permission</code></a>. Quatre guards existent (<code>web</code>, <code>admin</code>, <code>api</code>, <code>mobile</code>) ; trois rôles par défaut sont fournis (<code>super-admin</code>, <code>admin</code>, <code>user</code>), chacun avec un jeu de permissions par défaut. Voir <a href="./../admin-panel/user-role-management.html">Gestion d&#39;accès</a> pour l&#39;équivalent depuis l&#39;interface d&#39;administration.</p><p>Les endpoints <code>GET /roles</code> et <code>GET /permissions</code> sont publics ; la création/modification/suppression de rôles et permissions nécessite <code>auth:sanctum</code>. Certaines actions de gestion des utilisateurs (<code>POST /users</code>, <code>PUT /users/{user}</code>, <code>DELETE /users/{user}</code>...) exigent en plus une permission nommée précise (<code>action-add-user</code>, <code>action-edit-user</code>, <code>action-delete-user</code>...).</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fichier</th><th>Contenu</th></tr></thead><tbody><tr><td><code>config/auth.php</code></td><td>Guards (<code>web</code>, <code>admin</code>), providers, modèle utilisateur.</td></tr><tr><td><code>config/sanctum.php</code></td><td>Domaines stateful (<code>SANCTUM_STATEFUL_DOMAINS</code>), guards vérifiés (<code>web</code>, <code>admin</code>), expiration des tokens.</td></tr><tr><td><code>config/permission.php</code></td><td>Configuration de <code>spatie/laravel-permission</code> (tables, cache).</td></tr></tbody></table>',22)])])}const m=t(n,[["render",a]]);export{h as __pageData,m as default};
